head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > M > getDateFormat]<br/>Calendar 컴포넌트에 설정된 날짜 포맷 패턴 문자열을 반환합니다.",
    "validation" : [
        "현재 설정된 날짜 포맷 패턴 문자열을 String 타입으로 반환합니다.",
        "setDateFormat() 메소드로 별도 포맷을 설정하지 않은 경우 calendarValueType 속성에 따른 기본 포맷을 반환합니다.",
        "calendarValueType='yearMonth' 설정 시 setDateFormat() 미호출이면 'yyyyMM' 을 반환합니다.",
        "calendarValueType='yearMonthDate' 설정 시 setDateFormat() 미호출이면 'yyyyMMdd' 를 반환합니다.",
        "calendarValueType='yearMonthDateHour' 설정 시 setDateFormat() 미호출이면 'yyyyMMddHH' 를 반환합니다.",
        "calendarValueType='yearMonthDateTime' 설정 시 setDateFormat() 미호출이면 'yyyyMMddHHmm' 를 반환합니다.",
        "calendarValueType='yearMonthDateTimeSec' 설정 시 setDateFormat() 미호출이면 'yyyyMMddHHmmSS' 를 반환합니다.",
        "setDateFormat() 메소드로 별도 포맷을 설정한 경우 설정한 포맷 패턴 문자열을 반환합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        calendarValueType : con_calendarValueType.getText()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);

    // calendarValueType 별 자릿수에 맞춰 초기값 설정 (getFormattedValue 결과 확인용)
    let valueType = target1.options.calendarValueType || 'yearMonthDate';
    let initValue = '';
    if (valueType === 'yearMonth') {
        initValue = '202505';
    } else if (valueType === 'yearMonthDate') {
        initValue = '20250518';
    } else if (valueType === 'yearMonthDateHour') {
        initValue = '2025051812';
    } else if (valueType === 'yearMonthDateTime') {
        initValue = '202505181234';
    } else if (valueType === 'yearMonthDateTimeSec') {
        initValue = '20250518123456';
    }
    if (initValue !== '') {
        target1.gotoCalendar(initValue);
    }
}



// [공통] calendarValueType 적용값 + getDateFormat() 반환값
scwin.btn_getDateFormat_onclick = function (e) {
    let valueType = target1.options.calendarValueType;
    let dateFormat = target1.getDateFormat();

    // validation: calendarValueType 별 setDateFormat 미호출 시 기본 dateFormat 반환
    wf_body_bottom.getObj("scwin").setReturnValue("[calendarValueType 적용값] " + valueType);
    // validation: 현재 설정된 날짜 포맷 패턴 문자열을 String 타입으로 반환
    wf_body_bottom.getObj("scwin").setReturnValue("[getDateFormat() 반환] '" + dateFormat + "' (typeof=" + (typeof dateFormat) + ")");
};



// setDateFormat 으로 별도 포맷을 설정한 뒤 getDateFormat 으로 재확인
scwin.btn_setAndGetDateFormat_onclick = function (e) {
    let beforeFormat = target1.getDateFormat();
    let inputFormat = par_dateFormat.getValue();

    target1.setDateFormat(inputFormat);

    let afterFormat = target1.getDateFormat();

    // validation: setDateFormat 으로 설정한 패턴이 getDateFormat 으로 반환되는지 확인
    wf_body_bottom.getObj("scwin").setReturnValue("[setDateFormat 호출 전 getDateFormat()] '" + beforeFormat + "'");
    wf_body_bottom.getObj("scwin").setReturnValue("[setDateFormat 인자] '" + inputFormat + "'");
    wf_body_bottom.getObj("scwin").setReturnValue("[setDateFormat 호출 후 getDateFormat()] '" + afterFormat + "' (설정한 패턴 반환 여부: " + (afterFormat === inputFormat ? "예" : "아니오") + ")");
};
